#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>

#define MAX_SESSIONS 256
#define TOKEN_SECRET_LEN 32
#define MAX_PAYLOAD 512

static unsigned char g_secret[TOKEN_SECRET_LEN];
static int g_secret_initialized = 0;

typedef struct {
    char username[64];
    char role[32];
    uint32_t issued_at;
    uint32_t expires_at;
    int active;
} Session;

static Session g_sessions[MAX_SESSIONS];
static int g_session_count = 0;

void init_secret() {
    const char *env_secret = getenv("AUTH_SECRET");
    if (env_secret && strlen(env_secret) >= TOKEN_SECRET_LEN) {
        memcpy(g_secret, env_secret, TOKEN_SECRET_LEN);
    } else {
        FILE *f = fopen("/dev/urandom", "r");
        if (f) { fread(g_secret, 1, TOKEN_SECRET_LEN, f); fclose(f); }
    }
    g_secret_initialized = 1;
}

int hex_encode(const unsigned char *in, int in_len, char *out, int out_max) {
    if (out_max < in_len * 2 + 1) return -1;
    for (int i = 0; i < in_len; i++)
        sprintf(out + i*2, "%02x", in[i]);
    out[in_len*2] = '\0';
    return 0;
}

int hex_decode(const char *in, unsigned char *out, int out_max) {
    int len = strlen(in);
    if (len % 2 != 0 || len/2 > out_max) return -1;
    for (int i = 0; i < len/2; i++) {
        unsigned int byte;
        if (sscanf(in + i*2, "%02x", &byte) != 1) return -1;
        out[i] = (unsigned char)byte;
    }
    return len/2;
}

int compute_hmac(const char *data, int data_len, unsigned char *out) {
    unsigned int hmac_len = 0;
    HMAC(EVP_sha256(), g_secret, TOKEN_SECRET_LEN,
         (unsigned char*)data, data_len, out, &hmac_len);
    return (int)hmac_len;
}

/* Token format: base64(payload).hex(hmac)
   Payload format: session_id:issued_at:expires_at:username:role */

int create_session(const char *username, const char *role, int duration_seconds) {
    if (g_session_count >= MAX_SESSIONS) return -1;
    if (strlen(username) >= 63 || strlen(role) >= 31) return -2;

    // Validate characters
    for (int i = 0; username[i]; i++)
        if (!((username[i] >= 'a' && username[i] <= 'z') ||
              (username[i] >= 'A' && username[i] <= 'Z') ||
              (username[i] >= '0' && username[i] <= '9') ||
              username[i] == '_')) return -3;

    for (int i = 0; role[i]; i++)
        if (!((role[i] >= 'a' && role[i] <= 'z') ||
              (role[i] >= 'A' && role[i] <= 'Z'))) return -3;

    int sid = g_session_count++;
    memset(&g_sessions[sid], 0, sizeof(Session));
    strncpy(g_sessions[sid].username, username, 63);
    strncpy(g_sessions[sid].role, role, 31);
    g_sessions[sid].issued_at = (uint32_t)time(NULL);
    g_sessions[sid].expires_at = g_sessions[sid].issued_at + (uint32_t)duration_seconds;
    g_sessions[sid].active = 1;
    return sid;
}

int generate_token(int session_id, char *token_out, int token_max) {
    if (session_id < 0 || session_id >= g_session_count) return -1;
    Session *s = &g_sessions[session_id];

    char payload[MAX_PAYLOAD];
    int plen = snprintf(payload, MAX_PAYLOAD, "%d:%u:%u:%s:%s",
                        session_id, s->issued_at, s->expires_at,
                        s->username, s->role);
    if (plen < 0 || plen >= MAX_PAYLOAD) return -2;

    unsigned char hmac[32];
    compute_hmac(payload, plen, hmac);

    char hmac_hex[65];
    hex_encode(hmac, 32, hmac_hex, 65);

    int total = snprintf(token_out, token_max, "%s.%s", payload, hmac_hex);
    if (total < 0 || total >= token_max) return -3;
    return 0;
}

/* Verify token and check expiration.
 * Returns session_id on success, negative on failure.
 * 
 * Security: We verify HMAC first, then check expiration.
 * The expiration check uses the token's embedded expires_at
 * which is covered by the HMAC signature.
 */
int verify_token(const char *token) {
    if (!token || strlen(token) > 600) return -1;

    char buf[601];
    strncpy(buf, token, 600);
    buf[600] = '\0';

    // Find the last dot separator
    char *dot = strrchr(buf, '.');
    if (!dot || dot == buf) return -2;
    *dot = '\0';
    char *payload = buf;
    char *sig_hex = dot + 1;

    // Verify HMAC
    unsigned char expected_hmac[32];
    compute_hmac(payload, strlen(payload), expected_hmac);

    unsigned char provided_hmac[32];
    if (hex_decode(sig_hex, provided_hmac, 32) != 32) return -3;

    // Constant-time comparison
    unsigned char diff = 0;
    for (int i = 0; i < 32; i++)
        diff |= expected_hmac[i] ^ provided_hmac[i];
    if (diff != 0) return -4;

    // Parse payload fields
    int session_id;
    unsigned int issued_at, expires_at;
    char username[64], role[32];

    if (sscanf(payload, "%d:%u:%u:%63[^:]:%31s",
               &session_id, &issued_at, &expires_at,
               username, role) != 5) return -5;

    // Validate session_id bounds
    if (session_id < 0 || session_id >= g_session_count) return -6;
    if (!g_sessions[session_id].active) return -7;

    // Check expiration: compare token's expires_at against current time
    // Both are uint32_t values representing Unix timestamps
    time_t now = time(NULL);
    if ((int32_t)(expires_at - (uint32_t)now) < 0) {
        return -8; // Token expired
    }

    return session_id;
}

typedef struct {
    char action[16];
    char username[64];
    char role[32];
    char token[601];
    int duration;
    int resource_id;
} Request;

int parse_request(const char *input, Request *req) {
    memset(req, 0, sizeof(Request));
    req->duration = 3600; // default 1 hour

    const char *line = input;
    while (line && *line) {
        const char *nl = strchr(line, '\n');
        int line_len = nl ? (int)(nl - line) : (int)strlen(line);

        if (line_len > 0 && strncmp(line, "---", 3) == 0) break;

        char key[32] = {0}, value[601] = {0};
        if (sscanf(line, "%31[^:]: %600[^\n]", key, value) == 2) {
            if (strcmp(key, "Action") == 0) strncpy(req->action, value, 15);
            else if (strcmp(key, "Username") == 0) strncpy(req->username, value, 63);
            else if (strcmp(key, "Role") == 0) strncpy(req->role, value, 31);
            else if (strcmp(key, "Token") == 0) strncpy(req->token, value, 600);
            else if (strcmp(key, "Duration") == 0) req->duration = atoi(value);
            else if (strcmp(key, "ResourceId") == 0) req->resource_id = atoi(value);
        }
        line = nl ? nl + 1 : NULL;
    }
    return (req->action[0] != '\0') ? 0 : -1;
}

const char* access_resource(int session_id, int resource_id) {
    if (session_id < 0 || session_id >= g_session_count) return "error: invalid session";
    if (resource_id < 0 || resource_id > 99) return "error: invalid resource";

    // Admin check for privileged resources
    if (resource_id >= 50 && strcmp(g_sessions[session_id].role, "admin") != 0)
        return "error: admin required for resource >= 50";

    static char result[128];
    snprintf(result, sizeof(result), "resource_%d: data_for_%s",
             resource_id, g_sessions[session_id].username);
    return result;
}

void handle_request(const char *input) {
    Request req;
    if (parse_request(input, &req) != 0) {
        printf("error: invalid request\n");
        return;
    }

    if (strcmp(req.action, "create") == 0) {
        int sid = create_session(req.username, req.role, req.duration);
        if (sid < 0) { printf("error: create failed (%d)\n", sid); return; }
        char token[700];
        if (generate_token(sid, token, sizeof(token)) == 0)
            printf("token: %s\n", token);
        else
            printf("error: token generation failed\n");
    }
    else if (strcmp(req.action, "access") == 0) {
        int sid = verify_token(req.token);
        if (sid < 0) { printf("error: auth failed (%d)\n", sid); return; }
        printf("%s\n", access_resource(sid, req.resource_id));
    }
    else if (strcmp(req.action, "revoke") == 0) {
        int sid = verify_token(req.token);
        if (sid < 0) { printf("error: auth failed (%d)\n", sid); return; }
        g_sessions[sid].active = 0;
        printf("session %d revoked\n", sid);
    }
    else {
        printf("error: unknown action\n");
    }
}

int main() {
    init_secret();

    char input[4096];
    size_t total = 0;
    while (total < sizeof(input) - 1) {
        int c = fgetc(stdin);
        if (c == EOF) break;
        input[total++] = (char)c;
    }
    input[total] = '\0';

    handle_request(input);
    return 0;
}
